import type { ReactNode } from 'react';
import { View } from 'react-native';
import { KeyboardAwareScrollView } from 'react-native-keyboard-controller';
import { type Edge, SafeAreaView } from 'react-native-safe-area-context';

import { cn } from '@/lib/utils';

interface ScreenProps {
  children: ReactNode;
  /** Wrap content in a keyboard-aware scroll view. */
  scroll?: boolean;
  edges?: readonly Edge[];
  className?: string;
  contentClassName?: string;
}

/** Standard screen wrapper: safe-area insets, background, padding, optional scroll. */
export function Screen({
  children,
  scroll = false,
  edges = ['top', 'bottom'],
  className,
  contentClassName,
}: ScreenProps) {
  return (
    <SafeAreaView edges={edges} className={cn('flex-1 bg-background', className)}>
      {scroll ? (
        <KeyboardAwareScrollView
          contentContainerStyle={{ flexGrow: 1 }}
          keyboardShouldPersistTaps="handled"
          showsVerticalScrollIndicator={false}
          bottomOffset={24}
        >
          <View className={cn('flex-1 px-4 py-4', contentClassName)}>{children}</View>
        </KeyboardAwareScrollView>
      ) : (
        <View className={cn('flex-1 px-4 py-4', contentClassName)}>{children}</View>
      )}
    </SafeAreaView>
  );
}
